constexpr double nth(double x, int n) // 0<=n이라고 가정
{
    double res = 1;
    int i = 0;
    while (i<n) { // while 루프: 조건이 true일 동안 반복(1.7.1절)
        res*=x;
        ++i;
    }
    return res;
}

